linked_query:
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT (COUNT(?item) AS ?count)
WHERE { ?item wdt:P625 [] }

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?subProperties ?subPropertiesLabel WHERE {
?subProperties wdt:P1647* wd:P276.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?item ?name WHERE {
?item wdt:P138 wd:Q936580; wdt:P225 ?name
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?itemLabel ?img ?ann_date WHERE {
?item wdt:P361 wd:Q101791498;
wdt:P18 ?img;
wdt:P6949 ?ann_date
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT * WHERE {
?item wdt:P4033 ?mastodon; wdt:P19 ?pob. ?pob wdt:P625 ?coords.
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?s ?desc
WHERE
{
?s wdt:P279 wd:Q7725634 .
OPTIONAL {
?s rdfs:label ?desc FILTER (lang(?desc) = "en").
}
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?q ?name WHERE {
?q wdt:P428 ?name FILTER(STRSTARTS(?name,"H"))
} ORDER BY ?name

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?itemDescription ?model WHERE {
?item wdt:P4896 ?model; wdt:P195 [].
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,fr" }
} ORDER BY ?itemLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
?item ?itemLabel ?siteLink
WHERE {
?siteLink schema:about ?item;
schema:isPartOf <https://bn.wikisource.org/>;
wikibase:badge wd:Q20748093.
SERVICE wikibase:label { bd:serviceParam wikibase:language "bn,en".}
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT * WHERE {
?item wdt:P31 wd:Q1032372;
wdt:P625 ?geo .
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel
{
?item wdt:P2093 "Bill Thompson" .
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
?item ?itemLabel ?pic
WHERE
{
wd:Q96740175 wdt:P6803 ?item .
OPTIONAL {?item wdt:P18 ?pic}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?element ?elementLabel ?symbol ?number
WHERE
{
?element wdt:P31 wd:Q11344;
wdt:P246 ?symbol;
wdt:P1086 ?number.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?number

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?id (lang(?label) AS ?lang) ?label WHERE {
?item wdt:P2474 ?id;
rdfs:label ?label.
} ORDER BY ?id ?lang

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?wpid ?item ?itemLabel ?referenceLabel
WHERE
{
?item wdt:P2410 ?wpid ;
wdt:P2860 ?reference ;
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?q ?qLabel
WHERE
{
?q wdt:P31 wd:Q12355361.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?foundry ?foundryLabel ?rgb ?item ?itemLabel WHERE {
?item wdt:P31 wd:Q17451.
?item wdt:P4586 ?foundry.
BIND( "3182BD" AS ?rgb) #color code foundry nodes
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,fr,de". }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?subj ?label WHERE
{ ?subj wdt:P4102 ?atlasID ;
rdfs:label ?label filter (lang(?label) = "g1")
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?itemDescription ?value
{
?item wdt:P4896 ?value .
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,en" }
}
LIMIT 200

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?grandChild ?grandChildLabel
WHERE
{
wd:Q1339 wdt:P40 [ wdt:P40 ?grandChild ]. # Bach has as child someone who has a child ?grandChild.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT (COUNT(?alum) AS ?count)
WHERE
{
?alum wdt:P69 wd:Q34433.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?official_website WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
?item wdt:P1343 wd:Q76510930.
OPTIONAL { ?item wdt:P856 ?official_website. }
}
ORDER BY ASC(?itemLabel)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?denkmal ?denkmalLabel ?coordinates WHERE {
?denkmal wdt:P2424 ?id ;
wdt:P625 ?coordinates .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],de,en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?uniprotid ?tax_node
WHERE
{
?item wdt:P352 ?uniprotid ;
wdt:P703 wd:Q15978631 .
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

SELECT ?node ?predicate WHERE {
?node ?predicate "Wikidata"@en # @en is different from @en-gb and @en-ca
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?l ?word ?lemma WHERE {
VALUES ?word {'bought'@en}
?l a ontolex:LexicalEntry ;
dct:language wd:Q1860 ;
wikibase:lemma ?lemma ;
ontolex:lexicalForm ?form .
?form ontolex:representation ?word .
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?taxon ?eponym ?taxonLabel ?eponymLabel
WHERE
{
?taxon wdt:P31 wd:Q16521;
wdt:P138 ?eponym.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?eponym

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel
WHERE
{
?item wdt:P31 wd:Q2934.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?lexemeId ?lemma WHERE {
?lexemeId dct:language wd:Q9027;
wikibase:lemma ?lemma.
?lexemeId wikibase:lexicalCategory wd:Q9788
}
ORDER BY ?lemma

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?country ?countryLabel (COUNT(DISTINCT ?item) AS ?count) WHERE {
?item (wdt:P31|wdt:P279) wd:Q51404;
wdt:P17 ?country;
wdt:P571 ?time.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
ORDER BY (?countryLabel)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?length WHERE {
?item wdt:P31/wdt:P279* wd:Q4022 .
?item wdt:P2043 ?length .
FILTER ( ?length >= 1000 )
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
} ORDER BY DESC(?length) ?itemLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?property ?propertyLabel ?relation ?relationLabel WHERE {
?property p:P2302 ?statement.
?statement ps:P2302 wd:Q21510865;
pq:P2308 wd:Q43229;
pq:P2309 ?relation.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?composition ?composerLabel ?compositionLabel
WHERE
{
?composition wdt:P870/wdt:P279* wd:Q1444;
wdt:P870/wdt:P279* wd:Q42998;
wdt:P86 ?composer.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?Masonic_Lodge ?Masonic_LodgeLabel (sample(?Masonic_LodgeTitle) as ?wpTitle) WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
?Masonic_Lodge wdt:P31 wd:Q1454597.
OPTIONAL {
?article schema:about ?Masonic_Lodge ;
schema:name ?Masonic_LodgeTitle
}
} group by ?Masonic_Lodge ?Masonic_LodgeLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?c ?cLabel ?item ?itemLabel WHERE {
?item wdt:P31 wd:Q5335686.
?c wdt:P463 ?item
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY ?itemLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?image ?coords WHERE {
?item wdt:P31/wdt:P279* wd:Q12516 .
?item wdt:P17 wd:Q79 .
OPTIONAL { ?item wdt:P625 ?coords }
OPTIONAL { ?item wdt:P18 ?image }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
} ORDER BY ?itemLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select ?shape ?parkLabel ?image {
?park wdt:P31/wdt:P279* wd:Q46169 .
?park wdt:P17 wd:Q34 .
?park wdt:P3896 ?shape .
OPTIONAL { ?park wdt:P18 ?image . }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} limit 100

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?person ?personLabel ?positionLabel ?date (URI(CONCAT("https://discovery.nationalarchives.gov.uk/details/c/",?ukna)) AS ?url) WHERE {
?person wdt:P3029 ?ukna; # person in UK National Archives
wdt:P39 ?position . ?position wdt:P361 wd:Q112014. # held position in Cabinet of the UK
?person wdt:P570 ?date # death date
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?s ?desc ?linkcount
WHERE
{
?s wdt:P31 wd:Q37484 .
?s wikibase:sitelinks ?linkcount .
OPTIONAL {
?s rdfs:label ?desc FILTER (lang(?desc) = "en").
}
} GROUP BY ?s ?desc ?linkcount ORDER BY DESC(?linkcount)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT distinct ?event ?eventLabel ?date ?location ?image WHERE {
?event wdt:P136 wd:Q172980 ;
wdt:P577 ?date FILTER (YEAR(?date) <1925) .
OPTIONAL {?event wdt:P18 ?image .}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en, fr, de, it, es". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?subjectLabel ?coord ?image ?height ?subject WHERE {
?subject wdt:P31/wdt:P279* wd:Q41176 .
?subject wdt:P2048 ?height FILTER (?height > 300)
OPTIONAL {?subject wdt:P729 ?time .}
OPTIONAL {?subject wdt:P18 ?image .}
OPTIONAL {?subject wdt:P625 ?coord .}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en, fr" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT (COUNT(?thing) AS ?count) ?typeLabel WHERE {
?thing wdt:P1922 [];
wdt:P31 ?type.
SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,de,fr,ru"}
} GROUP BY ?typeLabel
ORDER BY DESC(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?state_of_Malaysia ?state_of_MalaysiaLabel ?area WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
?state_of_Malaysia wdt:P31 wd:Q15063586.
OPTIONAL { ?state_of_Malaysia wdt:P2046 ?area. }
}
ORDER BY(?area)
LIMIT 100

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?death ?itemLabel {
?item wdt:P31 wd:Q5 ; wdt:P106 wd:Q10349745 ; wdt:P509 wd:Q61037771 .
OPTIONAL { ?item wdt:P570 ?death }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?death

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel (MIN(?date) AS ?firstReleased) ?_image
WHERE {
?item wdt:P161 wd:Q221074;
wdt:P577 ?date
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
OPTIONAL { ?item wdt:P18 ?_image. }
} GROUP BY ?item ?itemLabel ?_image
ORDER BY (?date)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?obj ?objLabel ?objDescription ?char ?charLabel ?charDescription
WHERE {
?obj wdt:P138 ?char.
?char wdt:P1441/wdt:P50 wd:Q692 # Present in a work written by William Shakespeare
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
} ORDER By ASC(?work)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?child ?childLabel
WHERE
{
?child wdt:P22 wd:Q1339;
wdt:P25 wd:Q57487;
wdt:P106 wd:Q36834,
wd:Q486748.
# no indentation; makes it hard to distinguish between ; and ,
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE]". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?itemLabel ?shape (?itemLabel as ?layer)
WHERE
{
?item wdt:P31 wd:Q51041800 ;
wdt:P361 wd:Q922480 ;
wdt:P3896 ?shape .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?suburb ?suburbLabel ?coordinate_location WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
?suburb wdt:P31 wd:Q188509;
wdt:P17 wd:Q664.
OPTIONAL { ?suburb wdt:P625 ?coordinate_location. }
}
LIMIT 10000

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select ?actor ?actorLabel ?pobLabel ?geo ?image {
wd:Q83495 wdt:P161 ?actor .
# ?movie wdt:P179 wd:Q1210827 .
optional { ?actor wdt:P19 ?pob . }
optional { ?pob wdt:P625 ?geo . }
optional { ?actor wdt:P18 ?image . }
service wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?place ?placeLabel ?location WHERE
{
wd:Q64436 wdt:P625 ?arcLoc .
SERVICE wikibase:around {
?place wdt:P625 ?location .
bd:serviceParam wikibase:center ?arcLoc .
bd:serviceParam wikibase:radius "1" .
}
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en" .
}
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?software ?softwareLabel ?fsf ?hub ?fram ?logo WHERE {
?software (wdt:P31/wdt:P279*) wd:Q7397.
?software wdt:P361 wd:Q20712193.
OPTIONAL {?software wdt:P2537 ?fsf.}
OPTIONAL {?software wdt:P1972 ?hub.}
OPTIONAL {?software wdt:P4107 ?fram.}
OPTIONAL {?software wdt:P154 ?logo.}
