SELECT (COUNT(*) AS ?count) ?lexeme ?lemma {
?lexeme wikibase:lemma ?lemma ;
wdt:P5238 ?parts .
FILTER (!CONTAINS(?lemma, " "))
}
GROUP BY ?lexeme?lemma
ORDER BY DESC(?count)
LIMIT 100

