PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?lieuLabel ?contLabel (COUNT(DISTINCT ?researcher) AS ?nb) WHERE {
VALUES ?univ { wd:Q2303765 wd:Q1654025 wd:Q746079 }
?researcher (wdt:P108|wdt:P463|wdt:P1416) ?univ .
?researcher wdt:P27 ?lieu .
?lieu wdt:P30 ?cont .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?lieuLabel ?contLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?massifLabel ?elevation ?prominence ?isolation ?coords WHERE {
?item wdt:P361 ?massif .
?massif wdt:P361* wd:Q1286 .
OPTIONAL { ?item wdt:P2044 ?elevation . }
OPTIONAL { ?item wdt:P2660 ?prominence . }
OPTIONAL { ?item wdt:P2659 ?isolation . }
?item wdt:P625 ?coords .
FILTER ( ?prominence >= 1500 )
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
ORDER BY DESC(?prominence) ?itemLabel

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
