SELECT DISTINCT ?person ?personLabel (URI(CONCAT("http://viaf.org/viaf/",?viaf)) AS ?viaf_id) ?birthyear ?deathyear WHERE {
?person wdt:P106 wd:Q49757;
wdt:P27 wd:Q161885;
wdt:P569 ?birthdate;
wdt:P570 ?deathdate.
FILTER (!isBLANK(?birthdate))
FILTER (!isBLANK(?deathdate))
OPTIONAL{ ?person wdt:P214 ?viaf}
BIND(YEAR(?birthdate) AS ?birthyear)
BIND(YEAR(?deathdate) AS ?deathyear)
SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,de,fr,ru"}
} ORDER BY ?birthyear

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?coup ?coupLabel (MIN(?date) AS ?date_) (SAMPLE(?image) AS ?image_) WHERE {
?coup wdt:P31/wdt:P279* wd:Q45382;
wdt:P585 ?date. hint:Prior hint:rangeSafe true.
FILTER(?date >= "2001-00-00"^^xsd:dateTime
&& ?date < "2101-00-00"^^xsd:dateTime)
OPTIONAL { ?coup wdt:P18 ?image. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?coup ?coupLabel

