PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel (SAMPLE(?image) AS ?image) ?sitelinks WHERE {
{
?item wdt:P31/wdt:P279* wd:Q34379;
wdt:P170 wd:Q182011.
} UNION {
?item wdt:P31/wdt:P279* wd:Q1068162.
}
OPTIONAL { ?item wdt:P18 ?image. }
?item wikibase:sitelinks ?sitelinks.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?item ?itemLabel ?sitelinks
ORDER BY DESC(?sitelinks)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?sandwich ?ingredient ?sandwichLabel ?ingredientLabel
WHERE
{
?sandwich wdt:P31?/wdt:P279* wd:Q28803;
wdt:P527 ?ingredient.
MINUS { ?ingredient wdt:P279* wd:Q7802. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en", "fr". }
}
ORDER BY UCASE(STR(?sandwichLabel))

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT (SAMPLE(?seasonNumber) AS ?seasonNumber) (SAMPLE(?episodeNumber) AS ?episodeNumber) (SAMPLE(?title) AS ?title) (MIN(?pubDate) AS ?pubDate) ?episode
WHERE
{
# All episodes should be instance of episode with series Law & Order.
?episode wdt:P31 wd:Q21191270;
wdt:P179 wd:Q321423.
# Many of them also have the season as series, so we can get episode and season number from qualifiers there.
OPTIONAL {
?episode p:P179 [
ps:P179 [
# the season also has series Law & Order
p:P179 [
ps:P179 wd:Q321423;
pq:P1545 ?seasonNumber
]
];
pq:P1545 ?episodeNumber
].
}
OPTIONAL { ?episode wdt:P1476 ?title. }
OPTIONAL { ?episode wdt:P577 ?pubDate. }
}
GROUP BY ?episode # make sure we return each episode only once - a few have multiple publication dates, for example
ORDER BY IF(BOUND(?seasonNumber),xsd:integer(?seasonNumber),1000) xsd:integer(?episodeNumber) ?title

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT
?conf ?confLabel
?startDate ?endDate
?url
?hashtag
(GROUP_CONCAT(DISTINCT ?envLabel;separator=", ") AS ?environments)
(GROUP_CONCAT(DISTINCT ?orgLabel;separator=", ") AS ?organizers)
WHERE {
# web conferences with homepage
?conf wdt:P31/wdt:P279* wd:Q1543677 ;
wdt:P856 ?url .
OPTIONAL { # which software is used?
?conf wdt:P2283 ?env .
?env wdt:P31/wdt:P279* wd:Q7397
}
OPTIONAL { ?conf wdt:P580 ?startDate }
OPTIONAL { ?conf wdt:P582 ?endDate }
OPTIONAL { ?conf wdt:P2572 ?hashtag }
OPTIONAL { ?conf wdt:P664 ?org }
SERVICE wikibase:label {
bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" .
?conf rdfs:label ?confLabel .
?env rdfs:label ?envLabel .
?org rdfs:label ?orgLabel .
}
} GROUP BY ?conf ?confLabel ?url ?startDate ?endDate ?hashtag ?organizers

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?occ ?occLabel ?avgAge ?avgBirthYear ?count
WHERE
{
{
# Group the people by their occupation and calculate age
SELECT
?occ
(count(?p) as ?count)
(round(avg(?birthYear)) as ?avgBirthYear)
(avg(?deathYear - ?birthYear) as ?avgAge)
WHERE {
{
# Get people with occupation + birth/death dates; combine multiple birth/death dates using avg
SELECT
?p
?occ
(avg(year(?birth)) as ?birthYear)
(avg(year(?death)) as ?deathYear)
WHERE {
?p wdt:P31 wd:Q5 ;
wdt:P106 ?occ ;
p:P569/psv:P569 [
wikibase:timePrecision "9"^^xsd:integer ; # precision of at least year
wikibase:timeValue ?birth ;
] ;
p:P570/psv:P570 [
wikibase:timePrecision "9"^^xsd:integer ; # precision of at least year
wikibase:timeValue ?death ;
] .
}
GROUP BY ?p ?occ
}
}
GROUP BY ?occ
LIMIT 200
}
FILTER (?count > 300) # arbitrary number to weed out values with 'few' observations
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr" . }
}
ORDER BY ASC(?avgAge)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
?p ?pLabel ?comparewithLabel
(SAMPLE(?url) AS ?url_comp2)
WHERE
{
BIND(wd:Q39666 as ?comparewith)
hint:Query hint:optimizer "None".
{ ?comparewith ?wdt ?v.
?p wikibase:directClaim ?wdt; wikibase:propertyType wikibase:ExternalId.
FILTER NOT EXISTS { wd:Q4573 ?wdt [] }
FILTER NOT EXISTS { ?p wdt:P31 wd:Q66712599 }
FILTER NOT EXISTS { ?p wdt:P31 wd:Q27525351 }
FILTER NOT EXISTS { ?p wdt:P31 wd:Q66118402 }
OPTIONAL { ?p wdt:P1630 ?f. } BIND(URI(REPLACE(?f, "\\$1", ?v)) AS ?url)
} UNION { BIND( wd:Q4573 as ?p) }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en"}
}
GROUP BY ?p ?pLabel ?comparewithLabel
ORDER BY (?url_comp2)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?person ?personLabel ?personimage ?field ?fieldLabel WHERE {
{?person wdt:P21 wd:Q2449503 } UNION {?person wdt:P21 wd:Q1052281 } # trans men and women
?person wdt:P106/wdt:P279* wd:Q483501 . # artist
?person wdt:P106 ?field.
?field wdt:P279* wd:Q483501
MINUS {?field wdt:P279* wd:Q33999} # not actors
OPTIONAL{ ?person wdt:P18 ?personimage }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?animal ?animalLabel ?count
WITH {
SELECT DISTINCT ?animal ?statement WHERE {
?work wdt:P31/wdt:P279* wd:Q838948;
p:P180 ?statement.
?statement ps:P180 ?depicted.
MINUS { ?statement wikibase:rank wikibase:DeprecatedRank. }
?depicted wdt:P31? ?animal.
?animal wdt:P279+ wd:Q729.
MINUS { ?animal wdt:P279* wd:Q15978631. }
}
} AS %statements
WITH {
SELECT ?animal (SUM(COALESCE(?quantity, 1)) AS ?count) WHERE {
INCLUDE %statements.
OPTIONAL { ?statement pq:P1114 ?quantity. }
}
GROUP BY ?animal
HAVING(?count >= 10)
} AS %counts
WHERE {
INCLUDE %counts.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?region ?regionLabel ?country ?countryLabel ?area ?population ?density ?coords
WHERE
{
?region wdt:P31/wdt:P279* wd:Q10864048 ;
wdt:P17 ?country ;
wdt:P1082 ?population ;
p:P2046/psv:P2046 [
wikibase:quantityAmount ?baseArea ;
wikibase:quantityUnit [
p:P2370/psv:P2370 [
wikibase:quantityAmount ?unitArea;
wikibase:quantityUnit wd:Q25343
]
]
] ;
wdt:P625 ?coords .
FILTER NOT EXISTS { ?region wdt:P576 ?x }
BIND(?baseArea * ?unitArea / 1000000 AS ?area) .
FILTER ( ?area > 0 )
FILTER ( ?population > 0 )
BIND ((?population / ?area) AS ?density)
FILTER ( ?density < 30 )
?country wdt:P30 wd:Q46 .
FILTER NOT EXISTS { ?country wdt:P17 wd:Q3024240 }
FILTER NOT EXISTS { ?country wdt:P576 ?x }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?density ?countryLabel ?regionLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?geo ?layer WHERE {
?item (wdt:P31/(wdt:P279*)) wd:Q11707;
wdt:P166 wd:Q20824563;
wdt:P17 wd:Q32;
wdt:P625 ?geo.
?item p:P166 [ps:P166 wd:Q20824563; pq:P1114 ?layer]
MINUS {?item wdt:P576 []}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?prop ?propLabel ?count WHERE {
{
SELECT ?prop (COUNT(?ref) AS ?count) WHERE {
?prop wikibase:reference ?pr_pred . # the reference-specific form of a property
?ref ?pr_pred ?pr_obj . # to be found in any triple (any such triples will apply to references)
} GROUP BY ?pr_pred ?prop
}
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en"
}
} ORDER BY DESC (?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?countryLabel ?count WITH {
SELECT ?country (COUNT(DISTINCT ?human) AS ?count) WHERE {
?human wdt:P31 wd:Q5;
wdt:P27 ?country;
wdt:P1853 ?bloodType.
}
GROUP BY ?country
} AS %results WHERE {
INCLUDE %results.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?depicted ?depictedLabel ?ashcount ?ashexample ?ashexampleLabel ?clevcount ?clevexample ?clevexampleLabel WHERE {
{SELECT ?depicted (Sample(?itemash) AS ?ashexample) (COUNT(DISTINCT ?itemash) AS ?ashcount) (sample(?itemclev) as ?clevexample) (COUNT(DISTINCT ?itemclev) AS ?clevcount) WHERE {
?itemclev wdt:P195 wd:Q657415; wdt:P180 ?depicted.
?itemash wdt:P195 wd:Q636400 ; wdt:P180 ?depicted.
} GROUP BY ?depicted }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY DESC(?ashcount + ?clevcount)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?actor ?actorLabel ?characterLabel WHERE {
?actor wdt:P31 wd:Q5;
wdt:P21 wd:Q6581097;
wdt:P569 ?dob.
?movie1 wdt:P31/wdt:P279* wd:Q11424;
wdt:P179 ?trilogy;
p:P161 [
ps:P161 ?actor;
pq:P453 ?character
];
wdt:P577 ?movie1Publication.
?trilogy wdt:P31/wdt:P279* wd:Q13593818.
FILTER(?dob + "P20Y"^^xsd:duration <= ?movie1Publication && ?movie1Publication < ?dob + "P30Y"^^xsd:duration)
?movie2 wdt:P31/wdt:P279* wd:Q11424;
p:P161 [
ps:P161 ?actor;
pq:P453 ?character
];
wdt:P577 ?movie2Publication.
FILTER(?movie1Publication + "P40Y"^^xsd:duration < ?movie2Publication)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select ?item ?itemLabel ?coord ?layer where {
?item wdt:P31 wd:Q16970 .
{?item wdt:P417 wd:Q196527 .} union {?item wdt:P417 wd:Q239925 .}
?item wdt:P625 ?coord .
?item wdt:P17 wd:Q213 .
OPTIONAL {
?item wdt:P417 wd:Q196527 .
BIND("St. Wenceslas" AS ?layer).
}
OPTIONAL {
?item wdt:P417 wd:Q239925 .
BIND("St. Cyril and Methodius" AS ?layer).
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,cs". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?itemDescription ?location ?rgb ?image WITH {
SELECT $COUNTRY ?north ?east ?south ?west WHERE {
VALUES $COUNTRY { wd:Q212 }
$COUNTRY p:P1332 [psv:P1332 [wikibase:geoLatitude ?north]].
$COUNTRY p:P1334 [psv:P1334 [wikibase:geoLongitude ?east]].
$COUNTRY p:P1333 [psv:P1333 [wikibase:geoLatitude ?south]].
$COUNTRY p:P1335 [psv:P1335 [wikibase:geoLongitude ?west]].
} } AS %data
WHERE {
INCLUDE %data
?item wdt:P17 $COUNTRY .
?item p:P625 [
ps:P625 ?location ;
psv:P625 [
wikibase:geoLongitude ?longitude;
wikibase:geoLatitude ?latitude;
]
].
OPTIONAL { ?item wdt:P18 ?image }
FILTER (?latitude <= ?north && ?latitude >= ?south && ?longitude >= ?west && ?longitude <= ?east)
BIND ( (?north + ?south) / 2 AS ?centre )
BIND ( COALESCE(
IF(?latitude >= ?centre, "0057b7", 1/0),
"ffd700"
) AS ?rgb )
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
LIMIT 10000 # try to increase the limit but might timeout or cause browser to hang when rendering the map

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?person ?personLabel ?dob WITH {
SELECT ?photograph ?inception WHERE {
?photograph wdt:P31/wdt:P279* wd:Q125191;
wdt:P571 ?inception.
}
ORDER BY ?inception
LIMIT 1
} AS %earliestPhotograph WHERE {
?person wdt:P106/wdt:P279* wd:Q33231;
wdt:P569 ?dob.
INCLUDE %earliestPhotograph.
FILTER(?dob < ?inception)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?num ?itemDescription WHERE {
VALUES ?occ {wd:Q639669}
?item wdt:P31 wd:Q5 ;
wdt:P21 wd:Q6581072 ;
(wdt:P106/(wdt:P279*)) ?occ;
wdt:P106 ?occupation .
?item wikibase:sitelinks ?num.
?item wdt:P27 ?nacionalidad .
?nacionalidad wdt:P27 ?country .
?country (wdt:P361/(wdt:P361*)) wd:Q12585 .
FILTER(?num >= 1)
MINUS {
?art schema:about ?item.
?art schema:isPartOf <https://es.wikipedia.org/>.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "es,en". }
}
ORDER BY DESC(?num)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?coords (round(year(?date)/100) as ?layer ) ?img WHERE {
{
SELECT DISTINCT ?item (SAMPLE(?directcoords) AS ?directcoords) (SAMPLE(?placecoords) AS ?placecoords) (SAMPLE(?date) AS ?date) {
?item wdt:P195 wd:Q1376 ; wdt:P571 ?date .
?item p:P189 ?discoveryplaceS .
?discoveryplaceS ps:P189 ?discoveryplace .
OPTIONAL { ?discoveryplaceS pq:P625 ?directcoords . }
OPTIONAL { ?discoveryplace wdt:P625 ?placecoords . }
} GROUP BY ?item
}
BIND(COALESCE(?directcoords, ?placecoords) AS ?coords)
optional { ?item wdt:P18 ?img } .
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
?statue ?statueLabel (SAMPLE(?statueLocation) AS ?statueLocation_) (SAMPLE(?statueImage) AS ?statueImage_)
?person ?personLabel
(IF(?female, "female"@en, "not female"@en) AS ?femaleLabel)
(IF(?hasNobleTitle, "has noble title"@en, "has no noble title"@en) AS ?hasNobleTitleLabel)
(CONCAT(?femaleLabel, ", "@en, ?hasNobleTitleLabel) AS ?layer)
WHERE {
?statue wdt:P31/wdt:P279* wd:Q860861;
wdt:P17 wd:Q145;
wdt:P180|wdt:P547 ?person.
?person wdt:P31 wd:Q5.
BIND(EXISTS { ?person wdt:P21/wdt:P279* wd:Q6581072. } AS ?female)
BIND(EXISTS { ?person wdt:P97 ?nobleTitle. } AS ?hasNobleTitle)
OPTIONAL { ?statue wdt:P625 ?statueLocation. }
OPTIONAL { ?statue wdt:P18 ?statueImage. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?statue ?statueLabel ?person ?personLabel ?female ?hasNobleTitle

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item1 ?image ?item1Label ?item2 ?image2 ?item2Label ?edgeLabel
WITH { SELECT ?item1 WHERE {
VALUES ?item1 {wd:Q43380186 wd:Q93343 wd:Q43380245 wd:Q31561 wd:Q1302047 wd:Q47152 wd:Q55858204 wd:Q692 wd:Q82133 wd:Q47152 wd:Q56676227}
} } AS %item1
WITH {SELECT (?item1 AS ?item2) WHERE {INCLUDE %item1} } AS %item2
WHERE {
INCLUDE %item1.
INCLUDE %item2.
?item1 ?prop ?item2.
?edge wikibase:directClaim ?prop ; a wikibase:Property
OPTIONAL {?item1 wdt:P18 ?image}
OPTIONAL {?item2 wdt:P18 ?image2}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT (COUNT(?obj1) AS ?count) ?propertyLabel ?thingLabel ?thing WHERE {
?obj1 wdt:P195 wd:Q430682. #Tate
VALUES ?prop1 {wdt:P180 wdt:P170 wdt:P2348 wdt:P135 wdt:P136 wdt:P941 wdt:P186 wdt:P1071}
?obj1 ?prop1 ?thing.
?property ?ref ?prop1 ;
rdf:type wikibase:Property .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
} GROUP BY ?propertyLabel ?thingLabel ?thing ORDER BY DESC(?count) LIMIT 100

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX dbc: <http://dbpedia.org/resource/Category:>

SELECT DISTINCT ?wditem ?wditemLabel ?date ?image ?work ?workLabel ?coord WHERE {
SERVICE <http://dbpedia.org/sparql> {
?item dct:subject|dct:subject/skos:broader dbc:Illuminati_members ;
owl:sameAs ?wditem FILTER regex (?wditem, "wikidata.org") .
}
SERVICE <https://query.wikidata.org/sparql> {
{?wditem wdt:P569 ?date FILTER (YEAR(?date)<2050).}
#UNION
#{?wditem wdt:P571|wdt:P577|wdt:P580|wdt:P619 ?date .}
#{?wditem wdt:P625 ?coord .}
# OPTIONAL {?wditem wdt:P800 ?work. ?work rdfs:label ?workLabel FILTER (LANG(?workLabel)="en") .}
OPTIONAL {?wditem wdt:P18 ?image } .
?wditem rdfs:label ?wditemLabel FILTER (LANG(?wditemLabel)="en") .
}
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select distinct ?itemLabel ?size ?percentage_online ?rgb where {
?item wdt:P17 wd:Q213 .
?item p:P1436 ?statement.
?statement ps:P1436 ?size ;
pq:P585 ?date filter(year(?date)= 2021 )
minus {?statement pq:P518 [] .}
optional {?item p:P1436 [ps:P1436 ?size_online ; pq:P518 wd:Q106474029 ; pq:P585 ?date ] .}
bind ((100 * ?size_online / ?size) as ?percentage_online)
BIND(if
(?percentage_online < 10, "FF0000",
if (?percentage_online < 20, "E21C00",
if (?percentage_online < 30,"C63800",
if (?percentage_online < 40, "AA5500",
if (?percentage_online < 50, "8D7100",
if (?percentage_online < 60, "718D00",
if (?percentage_online < 70, "55AA00",
if (?percentage_online < 80, "38C600",
if (?percentage_online < 90, "1CE200", "00FF00"))))))))) as ?rgb) .
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,cs". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?airport ?airportLabel ?airportCountry ?airportCountryLabel ?person ?personLabel (sample(?birth) as ?birth) (SAMPLE(?death) as ?death) WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
?airport (wdt:P31/(wdt:P279*)) wd:Q1248784;
wdt:P17 ?airportCountry;
p:P138 ?statement.
?statement ps:P138 ?person.
?person wdt:P31 wd:Q5;
wdt:P106 wd:Q49757.
OPTIONAL { ?person wdt:P569 ?birth }
OPTIONAL { ?person wdt:P570 ?death }
FILTER(NOT EXISTS { ?statement pq:P582 ?endTime. })
} group by ?airport ?airportLabel ?airportCountry ?airportCountryLabel ?person ?personLabel ?personImage

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?label (SAMPLE(?coord) AS ?where) ?subj (?typeLabel AS ?layer) WHERE
{ ?subj wdt:P31/wdt:P279? ?type ;
wdt:P625 ?coord ;
wdt:P31 ?type ;
rdfs:label ?label filter (lang(?label) = "en").
?type wdt:P279? wd:Q744099 ;
rdfs:label ?typeLabel filter (lang(?typeLabel) = "en").
MINUS{?subj wdt:P18 []}
?subj p:P625/psv:P625 ?loc. # coordinate-location statement
?loc wikibase:geoLatitude ?lat .
?loc wikibase:geoLongitude ?long .
FILTER (?lat > 49) FILTER (?lat < 63)
FILTER (?long > -10.5) FILTER (?long < 2.02)
} GROUP BY ?label ?subj ?typeLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?path ?genes ?metabolites ?pathway WHERE {
{SELECT DISTINCT ?path (COUNT(?pwPart) AS ?genes) WHERE {
?path wdt:P2410 ?WikipathsID.
?path wdt:P527 ?pwPart.
?pwPart wdt:P31 wd:Q7187.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?path ?genes
}
{SELECT DISTINCT ?path (COUNT(?pwPart) AS ?metabolites) WHERE {
?path wdt:P2410 ?WikipathsID.
?path wdt:P527 ?pwPart.
?pwPart wdt:P31 wd:Q11173.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?path ?metabolites
}
OPTIONAL { ?path rdfs:label ?pathway. }
}
ORDER BY DESC(?genes)

PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?personLabel ?work ?workLabel ?pubyear ?englishwp ?englishws (SAMPLE(?fulltext) AS ?fulltext)
WHERE {
?person wdt:P1802 ?emlo.
?work wdt:P50 ?person.
MINUS {?work wdt:P31 wd:Q3331189}
OPTIONAL{?work wdt:P577 ?pubdate}
BIND(YEAR(?pubdate) as ?pubyear)
OPTIONAL{ ?englishwp schema:about ?work. ?englishwp schema:isPartOf <https://en.wikipedia.org/> }
OPTIONAL{ ?englishws schema:about ?work. ?englishws schema:isPartOf <https://en.wikisource.org/> }
OPTIONAL{ ?work wdt:[property:full work available at URL] ?fulltext }
FILTER (BOUND(?fulltext) {{!

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?person ?personLabel ?ee ?art ?artLabel ?image
WHERE {
?person wdt:P3429 ?ee;
wdt:P31 wd:Q5
SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,fr,de,es,it,sv,ru,pl,nl"}
?art wdt:P180 ?person;
wdt:P18 ?image
MINUS { ?person wdt:P18 ?image }
} ORDER BY ?personLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?type ?typeLabel (COUNT(?thing) AS ?things) WHERE {
?thing wdt:P2003 [];
wdt:P31 ?type.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
} GROUP BY ?type ?typeLabel
ORDER BY DESC(?things)

