OPTIONAL { ?person p:P1343/ps:P1343 ?source. ?source rdfs:label ?sourcename filter (lang(?sourcename) = "en")
OPTIONAL { ?ws schema:about ?source; schema:isPartOf <https://en.wikisource.org/> } }
