PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?p ?pLabel ?loc WITH {
SELECT ?p ?longitude ?test WHERE {
?p wdt:P17 wd:Q145 .
?p p:P625 [
psv:P625 [
wikibase:geoLongitude ?longitude ]
]
FILTER (ABS(?longitude + 1.83333) < 0.01)
} } AS %matches
WHERE {
INCLUDE %matches
?p wdt:P625 ?loc .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?language ?languageLabel ?count
WITH {
SELECT ?language (COUNT(DISTINCT ?lexeme) AS ?count) {
?lexeme dct:language ?language.
}
GROUP by ?language
} AS %result
WHERE {
INCLUDE %result
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER by DESC (?count)

PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?award ?awardLabel ?total ?women ?women_percentage
WHERE {
hint:Query hint:optimizer "None" .
{
SELECT ?award (COUNT(*) AS ?total) (SUM(IF(?gender = wd:Q6581072, 1, 0)) AS ?women) (ROUND(1000 / COUNT(*) * SUM(IF(?gender = wd:Q6581072, 1, 0))) / 10 AS ?women_percentage)
WHERE {
?human wdt:P166 ?award ; wdt:P21 ?gender ; wdt:P31 wd:Q5 .
}
GROUP BY ?award
ORDER BY DESC(?total)
LIMIT 200
} .
?award rdfs:label ?awardLabel .
FILTER (LANG(?awardLabel) = "en") .
}
ORDER BY DESC(?total)

