PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?givenName ?givenNameLabel (COUNT(DISTINCT ?character) AS ?count) ?authorClassification WHERE {
BIND(wd:Q121842 AS ?language)
?character wdt:P31/wdt:P279* wd:Q95074;
(wdt:P27/wdt:P37)|wdt:P103|wdt:P1412 ?language;
wdt:P735 ?givenName;
wdt:P170 ?author.
OPTIONAL { ?author (wdt:P27/wdt:P37)|wdt:P103|wdt:P1412 ?language. BIND(1 AS ?authorSpeaksLanguage) }
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en".
?givenName rdfs:label ?givenNameLabel.
?language rdfs:label ?languageLabel.
} hint:Prior hint:runLast false.
BIND(IF(BOUND(?authorSpeaksLanguage), ?languageLabel, "other"@en) AS ?authorClassification)
}
GROUP BY ?givenName ?givenNameLabel ?authorClassification
ORDER BY DESC(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?here ?count ?rank ?native_label ?itemLabel ?item ?itemDescription ?scriptLabel
WITH  { SELECT DISTINCT ?item (COUNT(DISTINCT ?p) as ?count) 
        WHERE { { ?item wdt:P460* wd:Q108636690 . ?p wdt:P735 ?item } UNION { ?item wdt:P460* wd:Q108636690 }  } 
        GROUP BY ?item ORDER BY DESC(?count) LIMIT 1000
      } AS %all
WITH  { SELECT (?item as ?item2) (?count AS ?count2) WHERE { INCLUDE %all }
      } AS %all2
WITH  { SELECT ?item (SUM(?x) AS ?rank) ?count WHERE { INCLUDE %all . INCLUDE %all2 . BIND( IF( ?count  <= ?count2 ,1,0) AS ?x ) } GROUP BY ?item ?count
      } AS %main 
WHERE
{ hint:Query hint:optimizer "None".    
  INCLUDE %main .
  OPTIONAL { FILTER( ?item = wd:Q108636690 )  BIND(" ==> " as ?here) }
  OPTIONAL { ?item wdt:P1705 ?native_label }
  OPTIONAL { ?item wdt:P282 ?script  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?person ?name ?birthplace ?birthyear ?coord ?layer WHERE {
{?person wdt:P106 wd:Q188094} UNION {?person wdt:P101 wd:Q8134} MINUS {?person wdt:P106 wd:Q188094; wdt:P101 wd:Q8134}
?person wdt:P570 ?dod;
wdt:P19 ?place .
?place wdt:P625 ?coord
OPTIONAL { ?person wdt:P569 ?dob }
BIND(YEAR(?dob) as ?birthyear)
BIND(IF( (?birthyear < 1700), "Pre-1700", IF((?birthyear < 1751), "1700-1750", IF((?birthyear < 1801), "1751-1800", IF((?birthyear < 1851), "1801-1850", IF((?birthyear < 1901), "1851-1900", IF((?birthyear < 1951), "1901-1950", "Post-1950") ) ) ) )) AS ?layer )
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en".?person rdfs:label ?name. ?place rdfs:label ?birthplace }
} ORDER BY ?birthyear

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT distinct ?item ?itemLabel ?date (GROUP_CONCAT(distinct ?creaLb; separator=" - ") as ?createur) ?img
WHERE {
?item wdt:P136 wd:Q1400612 ;
wdt:P170 ?crea ;
wdt:P18 ?img ;
p:P170 [ pq:P1777 wd:Q41264 ] ;
p:P571 ?declarationdate .
OPTIONAL { MINUS {?declarationdate pq:P1319 ?pasavant }
MINUS {?declarationdate pq:P1480 wd:Q5727902 }
?declarationdate ps:P571 ?dateunique .
BIND (year(?dateunique) AS ?date)}
OPTIONAL { MINUS {?declarationdate pq:P1319 ?pasavant }
?declarationdate pq:P1480 wd:Q5727902.
?declarationdate ps:P571 ?dateunique .
BIND (CONCAT("c.",STR(year(?dateunique))) AS ?date)}
OPTIONAL { ?declarationdate pq:P1319 ?pasavant .
?declarationdate pq:P1326 ?pasapres.
BIND (CONCAT(STR(year(?pasavant)),"-",STR(year(?pasapres))) AS ?date)}
?crea rdfs:label ?creaLb . filter (lang(?creaLb) = "fr") .
SERVICE wikibase:label {bd:serviceParam wikibase:language "fr"}
} GROUP BY ?item ?itemLabel ?date ?img

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX schema: <http://schema.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?article ?person ?personLabel ?picGrave ?coord ?bd ?graveplot2 ?layer WHERE {
{
?person wdt:P119 wd:Q311 ;
p:P119 [
pq:P965 ?graveplot];
wdt:P569 ?bd .
?person wdt:P19 ?city .
?city wdt:P625 ?coord .
OPTIONAL{ ?person wdt:P1442 ?picGrave .}
OPTIONAL {
?article schema:about ?person .
?article schema:inLanguage "fr" .
?article schema:isPartOf <https://fr.wikipedia.org/> .}
BIND (CONCAT("Division ",?graveplot) AS ?graveplot2)
BIND(
IF(?bd < "1700-01-01T00:00:00Z"^^xsd:dateTime, "<1700",
IF(?bd < "1800-01-01T00:00:00Z"^^xsd:dateTime, "18e siecle",
IF(?bd < "1900-01-01T00:00:00Z"^^xsd:dateTime, "19e siecle",
IF(?bd < "2000-01-01T00:00:00Z"^^xsd:dateTime, "20e siecle",
"21e siecle"))))
AS ?layer).
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr"}
}
Order by ?personLabel

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX p: <http://www.wikidata.org/prop/>
