PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?form ?lemma
WHERE {
?lexemeId dct:language wd:Q9027;
wikibase:lemma ?lemma;
ontolex:lexicalForm ?form.
MINUS {
?lexemeId p:P5831 ?statement.
?statement ps:P5831 ?example;
pq:P6072 [];
pq:P5830 ?form_with_example.
}
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX gas: <http://www.bigdata.com/rdf/gas#>

SELECT ?item ?itemLabel ?pic ?linkTo
WHERE
{
SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.SSSP" ;
gas:in wd:Q14001 ;
gas:traversalDirection "Reverse" ;
gas:out ?item ;
gas:out1 ?depth ;
gas:maxIterations 4 ;
gas:linkType wdt:P279 .
}
OPTIONAL { ?item wdt:P279 ?linkTo }
OPTIONAL { ?item wdt:P18 ?pic }
SERVICE wikibase:label {bd:serviceParam wikibase:language "en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel (SAMPLE(?typeLabel) AS ?_type) WHERE {
{ VALUES ?type { wd:Q108838260 wd:Q3343298 wd:Q17456916 wd:Q524778 wd:Q169180 } # Exec agencies (9) + NDPBs (45) + commissioners (7)
?item wdt:P31 ?type ;
wdt:P1001 wd:Q22 .
MINUS { ?item wdt:P31 wd:Q5532360 }
}
UNION
{ ?item wdt:P31 wd:Q270791; # Public corps (6)
wdt:P127 wd:Q32521 .
}
UNION
{ VALUES ?type { wd:Q18392368 wd:Q1412224 wd:Q3044788 wd:Q327333 wd:Q104417453 } # Tribunals (11) + other (28)
?item wdt:P31 ?type ;
wdt:P131|wdt:P1001 wd:Q22 .
MINUS { ?item wdt:P1001 wd:Q1156248 }
MINUS { ?item p:P1001 ?js . ?js pq:P582 [] }
}
UNION
{ VALUES ?type { wd:Q21451686 wd:Q83425186 wd:Q20667323 } # Local authorities (32) + Health boards (14)
?item wdt:P31 ?type .
}
UNION
{ ?item wdt:P361 wd:Q4993654 . # Courts (56)
}
MINUS { ?item wdt:P576 [] }
OPTIONAL { ?item wdt:P31 ?type }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". ?type rdfs:label ?typeLabel . ?item rdfs:label ?itemLabel }
} GROUP BY ?item ?itemLabel

