SELECT DISTINCT ?alum ?alumLabel ?alumDescription ?image
WHERE {
{?alum wdt:P69 wd:Q34433 .}
UNION {?college wdt:P31 wd:Q2581649.
?alum wdt:P69 ?college.}
?alum wdt:P21 wd:Q6581072 .
MINUS { ?alum wdt:P27 wd:Q145 }.
OPTIONAL {?alum wdt:P18 ?image }.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

select (STR(?year1) as ?year) ((count(?item) * ?sgn) as ?count) ?layer where {
?item wdt:P19/wdt:P17 ?country . values ?country {wd:Q213 wd:Q183} . ?item wdt:P569 ?birthdate bind((FLOOR(YEAR(?birthdate)/10)*10) as ?year1) FILTER(?year1>=1800).
optional {?item wdt:P19/wdt:P17 wd:Q213 . ?item wdt:P20/wdt:P17 wd:Q183 . bind("Born in Czechia, died in Germany" as ?layer). bind(1 as ?sgn)}
optional {?item wdt:P19/wdt:P17 wd:Q183 . ?item wdt:P20/wdt:P17 wd:Q213 . bind("Born in Germany, died in the Czech Republic" as ?layer). bind(-1 as ?sgn)}
filter(bound(?layer)) .
}
group by ?year1 ?layer ?sgn
order by asc(?year1)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT (?namesLabel AS ?name) (COUNT(?monarch) AS ?dead_monarchs) (SAMPLE(?cause_of_deathLabel) AS ?causes_of_death) WHERE {
VALUES ?monarchies {wd:Q9134365 wd:Q111722535 wd:Q110324075 wd:Q18810062}
?monarch wdt:P39 ?monarchies;
wdt:P735 ?names.
?monarch wdt:P1196 ?cause_of_death.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en".
?names rdfs:label ?namesLabel .
?monarch rdfs:label ?monarchLabel .
?cause_of_death rdfs:label ?cause_of_deathLabel .}
} GROUP BY ?namesLabel ?cause_of_death
ORDER BY DESC (?dead_monarchs)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?depicted ?depictedLabel ?ashcount ?ashexample ?ashexampleLabel ?clevcount ?clevexample ?clevexampleLabel WHERE {
{SELECT ?depicted (Sample(?itemash) AS ?ashexample) (COUNT(DISTINCT ?itemash) AS ?ashcount) (sample(?itemclev) as ?clevexample) (COUNT(DISTINCT ?itemclev) AS ?clevcount) WHERE {
?itemclev wdt:P195 wd:Q657415; wdt:P180 ?depicted.
?itemash wdt:P195 wd:Q636400 ; wdt:P180 ?depicted.
} GROUP BY ?depicted }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY DESC(?ashcount + ?clevcount)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?country1Label ?country2Label ?capital1Label ?capital2Label ?distance WHERE {
{
SELECT DISTINCT ?country1 ?country2 ?capital1 ?capital2 ?distance WHERE {
?country1 p:P463 ?statement1 ;
wdt:P36 ?capital1 .
?statement1 ps:P463 wd:Q1065 .
FILTER NOT EXISTS { ?statement1 pq:P582 ?x }
FILTER NOT EXISTS { ?country1 wdt:P31 wd:Q3024240 }
?country2 p:P463 ?statement2 ;
wdt:P36 ?capital2 .
?statement2 ps:P463 wd:Q1065 .
FILTER NOT EXISTS { ?statement2 pq:P582 ?x }
FILTER NOT EXISTS { ?country2 wdt:P31 wd:Q3024240 }
?capital1 wdt:P625 ?coords1 .
?capital2 wdt:P625 ?coords2 .
FILTER(xsd:string(?country1) < xsd:string(?country2))
FILTER NOT EXISTS {
?country1 p:P47 ?statementBorder .
?statementBorder ps:P47 ?country2 .
{ FILTER NOT EXISTS { ?statementBorder pq:P5102 ?x } } UNION
{ ?statementBorder pq:P5102 wd:Q15104814 }
}
BIND(ROUND(geof:distance(?coords1, ?coords2)) AS ?distance) .
FILTER (?distance<200)
}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?distance

