SELECT (COUNT(DISTINCT ?lexeme) AS ?lexeme_count) ?dictionaries_count (SAMPLE(?lexeme) AS ?sample) {
SELECT ?lexeme (COUNT(DISTINCT ?wdt) AS ?dictionaries_count) {
