PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?river ?riverLabel ?length ?continent ?continentLabel WITH {
SELECT DISTINCT ?river ?length {
?river wdt:P31 wd:Q4022 ; wdt:P17 wd:Q142 ; wdt:P2043 ?length .
FILTER NOT EXISTS { ?department wdt:P31/wdt:P279* wd:Q6465 ; wdt:P138 ?river }
}
ORDER BY DESC(?length)
LIMIT 10
} AS %i WHERE {
INCLUDE %i
OPTIONAL { ?river wdt:P4614/wdt:P30 ?continent }
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr" }
}
ORDER BY DESC(?length)

