PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?s ?sLabel ?coor ?layer ?typeLabel ?website ?end ?end1
WHERE {
hint:Query hint:optimizer "None" .
?s wdt:P131* wd:Q25 .
{ ?s wdt:P31/wdt:P279* wd:Q33506 }
UNION { ?s wdt:P31/wdt:P279* wd:Q7075 }
UNION { ?s wdt:P31/wdt:P279* wd:Q166118 } .
?s wdt:P625 ?coor .
?s wdt:P31 ?type .
?type wdt:P279* wd:Q1030034 .
OPTIONAL { ?s wdt:P856 ?website . }
OPTIONAL { ?s wdt:P576 ?end . }
OPTIONAL { ?s wdt:P582 ?end1 . }
FILTER NOT EXISTS { ?s wdt:P576 ?end }.
FILTER NOT EXISTS { ?s wdt:P582 ?end1}.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT
?person ?personLabel
(SAMPLE(CONCAT(?award1Label, " (", ?country1Label, ")")) AS ?firstAward)
(SAMPLE(CONCAT(?award2Label, " (", ?country2Label, ")")) AS ?secondAward)
WHERE {
?person wdt:P31 wd:Q5;
wdt:P166 ?award1, ?award2.
wd:Q1788716 ^(wdt:P31|wdt:P279)* ?award1, ?award2.
FILTER(?award1 != ?award2).
?award1 wdt:P17 ?country1.
?award2 wdt:P17 ?country2.
FILTER(?country1 != ?country2).
FILTER((?country1 != wd:Q159 || ?country2 != wd:Q15180) && (?country1 != wd:Q15180 || ?country2 != wd:Q159)).
OPTIONAL { ?person rdfs:label ?personLabel. FILTER(LANG(?personLabel) = "en"). }
OPTIONAL { ?award1 rdfs:label ?award1Label. FILTER(LANG(?award1Label) = "en"). }
OPTIONAL { ?award2 rdfs:label ?award2Label. FILTER(LANG(?award2Label) = "en"). }
OPTIONAL { ?country1 rdfs:label ?country1Label. FILTER(LANG(?country1Label) = "en"). }
OPTIONAL { ?country2 rdfs:label ?country2Label. FILTER(LANG(?country2Label) = "en"). }
}
GROUP BY ?person ?personLabel
LIMIT 50

