?person wdt:P4478 ?accused .
?person wdt:P106 ?occupation.
}
GROUP BY ?occupation
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?count)
LIMIT 1000

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?person ?name ?birthyear ?deathyear ?enws ?quotes ?commonscat
(URI(CONCAT("https://www.gutenberg.org/ebooks/author/", ?gutenberg_id)) AS ?gutenberg)
(URI(CONCAT("https://doi.org/10.1093/ref:odnb/", ?odnb)) AS ?odnburl)
(URI(CONCAT("http://onlinebooks.library.upenn.edu/webbin/book/lookupname?key=", ?books)) AS ?booksurl)
(URI(CONCAT("https://www.britannica.com/", ?britannica)) AS ?britannicaurl) ?npg WHERE {
{ ?person wdt:P106 wd:Q188094 }
UNION
{ ?person wdt:P101 wd:Q8134 }
OPTIONAL {?person wdt:P1938 ?gutenberg_id}
OPTIONAL { ?person wdt:P4629 ?books }
OPTIONAL {
?enws schema:about ?person;
schema:isPartOf <https://en.wikisource.org/>
}
FILTER (BOUND(?enws) || BOUND(?gutenberg_id) || BOUND(?books))
OPTIONAL { ?person wdt:P570 ?death }
BIND(YEAR(?death) AS ?deathyear)
OPTIONAL { ?person wdt:P569 ?birth }
BIND(YEAR(?birth) AS ?birthyear)
OPTIONAL { ?person wdt:P1417 ?britannica }
OPTIONAL { ?person wdt:P1816 ?npg }
OPTIONAL { ?person wdt:P373 ?commonscat }
OPTIONAL {
?quote schema:about ?person;
schema:isPartOf <https://en.wikiquote.org/>
}
OPTIONAL { ?person wdt:P1415 ?odnb }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". ?person rdfs:label ?name }
}
ORDER BY ?deathyear

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?coordinates ?line ?station ?stationLabel ?connectLabel ?image ?opening ?rgb
WITH {
SELECT ?station ?coordinates ?image ?lat ?lon ?opening WHERE {
{
SELECT ?station (SAMPLE(?coord_stmt) AS ?coord_stmt) (SAMPLE(?image) AS ?image) (sample(?opening) as ?opening) WHERE {
?station wdt:P31/wdt:P279* wd:Q55488 .
?station wdt:P361 wd:Q260870 .
?station p:P625 ?coord_stmt .
OPTIONAL { ?station wdt:P18 ?image }.
OPTIONAL { ?station wdt:P1619 ?opening }.
} GROUP BY ?station
}
hint:SubQuery hint:optimizer "None".
?coord_stmt ps:P625 ?coordinates .
?coord_stmt psv:P625 / wikibase:geoLatitude ?lat .
?coord_stmt psv:P625 / wikibase:geoLongitude ?lon .
}
} AS %stations
WITH {
SELECT (?station AS ?nextstation) (?lat AS ?lat2) (?lon AS ?lon2) WHERE {
INCLUDE %stations
}
} AS %nextstations
WITH {
SELECT ?line ?connect ?rgb WHERE {
INCLUDE %stations .
INCLUDE %nextstations .
?station p:P197 ?nextstationstatement .
?nextstationstatement ps:P197 ?nextstation .
?nextstationstatement pq:P81 ?connect . ?connect wdt:P361 wd:Q260870 .
?connect wdt:P465 ?rgb .
FILTER(STR(?station) < STR(?nextstation)) .
BIND(CONCAT('LINESTRING (', STR(?lon), ' ', STR(?lat), ',', STR(?lon2), ' ', STR(?lat2), ')') AS ?str) .
BIND(STRDT(?str, geo:wktLiteral) AS ?line)
}
} AS %lines
WHERE {
{ INCLUDE %stations } UNION { INCLUDE %lines } .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?placeLabel ?placeDescription ?image ?coord WHERE {
wd:Q64 wdt:P625 ?berlinLoc .
SERVICE wikibase:around {
?place wdt:P625 ?location .
bd:serviceParam wikibase:center ?berlinLoc .
bd:serviceParam wikibase:radius "10" .
} .
FILTER EXISTS { ?place wdt:P31/wdt:P279* wd:Q23397 }
OPTIONAL { ?place wdt:P18 ?image.}
SERVICE wikibase:label {
bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" .
}
}

