SELECT DISTINCT ?item ?itemLabel ?image ?coords
WHERE
{
?item wdt:P31/wdt:P279* wd:Q2977 ;
wdt:P17 wd:Q142 ;
wdt:P625 ?coords ;
wdt:P18 ?image .
FILTER NOT EXISTS { ?item wdt:P5816 wd:Q56556915 }
{ ?item wdt:P131 wd:Q90 } UNION
{ ?item wdt:P131/wdt:P131 wd:Q90 } UNION
{ ?item wdt:P131/wdt:P131/wdt:P131 wd:Q90 }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?itemLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
