PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?langLabel ?langDate ?humanLabel ?picture WHERE {
?lang (wdt:P31/(wdt:P279*)) wd:Q9143.
?human wdt:P31 wd:Q5;
