PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?state ?stateLabel ?capital ?capitalLabel WHERE {
?state wdt:P31/wdt:P279* wd:Q3624078;
wdt:P36 ?capital.
MINUS { ?state wdt:P576|wdt:P582 ?end. }
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en".
?state rdfs:label ?stateLabel.
?capital rdfs:label ?capitalLabel.
} hint:Prior hint:runLast false.
BIND(CONCAT("^[", ?stateLabel, "]*$") AS ?regex)
FILTER(REGEX(?capitalLabel, ?regex, "i"))
MINUS { ?capital wdt:P138 ?state. }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT ?item ?itemLabel_ol ?official_language ?itemLabel_en WHERE {
?item wdt:P30 wd:Q15 ;
wdt:P37 ?officiallanguage ;
wdt:P31 wd:Q6256 .
?officiallanguage wdt:P424 ?langcode .
?item rdfs:label ?itemLabel_ol . FILTER(lang(?itemLabel_ol)=?langcode)
?item rdfs:label ?itemLabel_en . FILTER(lang(?itemLabel_en)='en')
?officiallanguage rdfs:label ?official_language . FILTER(lang(?official_language)='en')
}
ORDER BY ?item ?itemLabel_ol ?official_language

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX gas: <http://www.bigdata.com/rdf/gas#>

SELECT ?item ?itemLabel ?sitelinks {
SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.SSSP" ;
gas:in wd:Q291877 ;
gas:traversalDirection "Forward" ;
gas:out ?item ;
gas:linkType wdt:P40 .
}
?item wdt:P21 wd:Q6581072.
?item wdt:P569 ?jaiotza.
?item wdt:P106 wd:Q33999.
?item wikibase:sitelinks ?sitelinks.
BIND(YEAR(?jaiotza) as ?year).
FILTER(?year > 1950).
MINUS{?item wdt:P570 ?heriotza}.
SERVICE wikibase:label {bd:serviceParam wikibase:language "eu,es,en" }
}
order by desc(?sitelinks)

