PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?line ?coords ?length WHERE {
{
?item wdt:P31 wd:Q80830021.
OPTIONAL {
?item p:P625 ?coords_stmt_west.
?coords_stmt_west pq:P518 wd:Q80981719;
ps:P625 ?coords_west;
(psv:P625/wikibase:geoLatitude) ?lat1;
(psv:P625/wikibase:geoLongitude) ?lon1.
}
OPTIONAL {
?item p:P625 ?coords_stmt_east.
?coords_stmt_east pq:P518 wd:Q80982256;
ps:P625 ?coords_east;
(psv:P625/wikibase:geoLatitude) ?lat2;
(psv:P625/wikibase:geoLongitude) ?lon2.
}
OPTIONAL { ?item wdt:P2043 ?length. }
BIND(CONCAT("LINESTRING (", STR(?lon1), " ", STR(?lat1), ",", STR(?lon2), " ", STR(?lat2), ")") AS ?str)
BIND(STRDT(?str, geo:wktLiteral) AS ?line)
}
UNION
{
?item wdt:P31 wd:Q80962689;
wdt:P625 ?coords.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY (?coords_west)

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wikibase: <http://wikiba.se/ontology#>

select *
with {
select ?lang (count(*) as ?meaningless) {
?l dct:language ?lang;
wikibase:statements "0"^^xsd:integer.
minus { ?l ontolex:sense [] }
} group by ?lang
} as %meaningless
with {
select ?lang (count(*) as ?total) {
?l dct:language ?lang.
} group by ?lang
} as %totals
where {
include %meaningless.
include %totals.
filter (?total >= 10).
bind(?meaningless/?total*100 as ?pc).
?lang rdfs:label ?en filter(lang(?en) = "en").
} order by desc(?pc) desc(?total) ?en

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?employerLabel ?logoImage ?NoVBIBFix (COUNT(?vbib) AS ?NoVBIB) WITH {
SELECT DISTINCT ?employer ?vbib ?logoImage WHERE {
?vbib wdt:P179 wd:Q108784175.
?presentation wdt:P5072 ?vbib;
wdt:P585 ?pit.
BIND(YEAR(?pit) AS ?year)
?presentation wdt:P50 ?author.
?author p:P108 ?employerStmt.
?employerStmt ps:P108 ?employer.
OPTIONAL { ?employerStmt pq:P580 ?empStart.
}
FILTER (?pit > ?empStart)
OPTIONAL { ?employerStmt pq:P582 ?empEnd.
}
FILTER ((bound(?empEnd) && ?pit < ?empEnd) || (!bound(?empEnd) && ?pit > ?empStart) )
OPTIONAL {?employer wdt:P154 ?logoImage.}
}
}AS %results
WHERE {
INCLUDE %results.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
{
SELECT (COUNT(?vbib) AS ?NoVBIBFix) WHERE {
?vbib wdt:P179 wd:Q108784175.
}
}
}
GROUP BY ?employerLabel ?NoVBIBFix ?logoImage
HAVING (COUNT(?vbib)=?NoVBIBFix)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?image ?distanceMiles ?coords WHERE {
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
wd:Q188740 wdt:P625 ?MoMA.
SERVICE wikibase:around {
?item wdt:P625 ?coords.
bd:serviceParam wikibase:center ?MoMA;
wikibase:radius "3.21869";
wikibase:distance ?distance.
}
FILTER(EXISTS { ?item (wdt:P31/(wdt:P279*)) wd:Q33506. })
OPTIONAL { ?item wdt:P18 ?image. }
BIND(CONCAT(STR((ROUND(?distance * "62.1371192"^^xsd:decimal)) / 100 ), " miles FROM MoMA") AS ?distanceMiles)
}
ORDER BY (?distance)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel (GROUP_CONCAT(DISTINCT ?occupationLabel; SEPARATOR = ", ") AS ?occupations) (GROUP_CONCAT(DISTINCT ?countryLabel; SEPARATOR = ", ") AS ?countries) ?birth ?articles WHERE {
VALUES ?occ {wd:Q15253558}
?item wdt:P31 wd:Q5;
wdt:P21 wd:Q6581072;
wdt:P27 ?country;
(wdt:P106/(wdt:P279*)) ?occ;
wdt:P106 ?occupation;
wikibase:sitelinks ?articles;
wdt:P569 ?birth.
?country p:P361/ps:P361 wd:Q12585 .
hint:Prior hint:rangeSafe "true"^^xsd:boolean.
FILTER((?birth >= "1900-01-01T00:00:00"^^xsd:dateTime) && (?birth < "1999-01-01T00:00:00"^^xsd:dateTime))
SERVICE wikibase:label {
bd:serviceParam wikibase:language "es,en".
?item rdfs:label ?itemLabel.
?gender rdfs:label ?genderLabel.
?occupation rdfs:label ?occupationLabel.
?country rdfs:label ?countryLabel.
}
}
GROUP BY ?item ?itemLabel ?genderLabel ?birth ?articles
ORDER BY DESC (?articles)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pqv: <http://www.wikidata.org/prop/qualifier/value/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?wetenschapper ?wetenschapperLabel ?university ?universityLabel ?twitter ?followers (CONCAT("https://twitter.com/",?twitter) AS ?twitterlink) ?pic WHERE {
?wetenschapper wdt:P108|wdt:P1416 ?university ;
p:P2002 ?twitterSt .
OPTIONAL { ?wetenschapper wdt:P18 ?pic . }
?twitterSt ps:P2002 ?twitter .
OPTIONAL { ?twitterSt pqv:P8687/wikibase:quantityAmount ?followers . }
?university wdt:P31 wd:Q3918 ;
wdt:P17 wd:Q55 .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY DESC(?followers)

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?sense ?lexeme ?lemma ?genre ?genreLabel WHERE {
?lexeme rdf:type ontolex:LexicalEntry;
dct:language wd:Q150;
wikibase:lemma ?lemma;
ontolex:sense ?sense;
wdt:P5185 ?genre.
?sense wdt:P5137 ?item.
?item (wdt:P31/(wdt:P279*)) wd:Q12737077;
rdfs:label ?itemLabel.
FILTER((LANG(?itemLabel)) = "fr")
?genre rdfs:label ?genreLabel.
FILTER((LANG(?genreLabel)) = "fr")
}
ORDER BY (?item) (?lemma) (?genre)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX pr: <http://www.wikidata.org/prop/reference/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select ?lexemeId ?lemma ?example ?sourceLabel ?source
WHERE {
?lexemeId <http://purl.org/dc/terms/language> wd:Q9027;
wikibase:lemma ?lemma.
?lexemeId p:P5831 ?statement.
?statement ps:P5831 ?example;
pq:P6072 [];
pq:P5830 [].
?lexemeId p:P5831 [ prov:wasDerivedFrom [ pr:P248 ?source ] ].
SERVICE wikibase:label { bd:serviceParam wikibase:language "sv,en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?composerLabel ?tonalityLabel ?count
WHERE
{
{
# 4. Group again, this time just by the composer.
# We also select the highest count of a tonality.
# Notice that we don't know what tonality this count is associated with - we'll get to that.
# So now we have each composer, along with how often they used whatever tonality they used most.
SELECT ?composer (MAX(?count) AS ?count)
WHERE
{
{
# 2. Group by composer and tonality, so that for each composer and tonality, we get a count of how often the composer used this tonality.
SELECT ?composer ?tonality (COUNT(?composition) AS ?count)
WHERE
{
# 1. Extremely straightforward: the ?composition has the composer ?composer and the tonality ?tonality.
# (I'm not bothering with any "instance of" because the presence of these two properties is a sufficient indicator of ?composition being a composition.)
?composition wdt:P86 ?composer;
wdt:P826 ?tonality.
}
GROUP BY ?composer ?tonality
HAVING(?count > 1) # 3. Limit that to counts > 1, because using a tonality once is hardly "most used".
}
}
GROUP BY ?composer
}
{
# 6. Identical to 2.
SELECT ?composer ?tonality (COUNT(?composition) AS ?count)
WHERE
{
# 5. Identical to 1.
?composition wdt:P86 ?composer;
wdt:P826 ?tonality.
}
GROUP BY ?composer ?tonality
HAVING(?count > 1) # 7. Identical to 3.
}
# 8. That's it. Wait, what?
# From 4, we now have ?composer, any composer, and ?count, the count of how often they used whatever tonality they used most.
# From 6, we also have a ?composer, as well as a ?tonality, and the count of how often they used that particular tonality.
# The trick is that ?composer and ?count are the same variable in each subquery, and so now, when the two subqueries are joined,
# we select only that ?tonality from 6 where the ?composer and the ?count are identical to those from 4 -
# that is, where this tonality was used as often as the composer's most-used tonality.
# In other words, this must *be* the composer's most-used tonality (except when there are multiple tonalities with the same count).
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?count) # 9. Order by count (highest first), because the result isn't very meaningful for low counts (many compositions aren't on Wikidata or don't have a tonality statement).

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT
?item
?itemLabel
?communeLabel
(group_concat(distinct ?merimee ; separator = ", ") as ?merimee)
?coords
?image
WHERE {
{
SELECT DISTINCT ?item ?merimee WHERE {
?item wdt:P1435/wdt:P279* wd:Q916475 .
?item p:P1435 ?heritage_statement .
FILTER NOT EXISTS { ?heritage_statement pq:P582 ?end . }
?item wdt:P380 ?merimee.
}
ORDER BY ?merimee
}
?item wdt:P131/wdt:P131* wd:Q3068 .
?item wdt:P131 ?commune .
OPTIONAL { ?item wdt:P625 ?coords . }
OPTIONAL { ?item wdt:P18 ?image . }
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr" . }
}
GROUP BY ?item ?itemLabel ?communeLabel ?coords ?image
ORDER BY ?communeLabel ?itemLabel

