PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX gas: <http://www.bigdata.com/rdf/gas#>

SELECT ?station ?stationLabel ?cds ?line ?trackLabel ?track ?image {
{SELECT * {
SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.BFS" ; gas:in wd:Q1990205 ; gas:out ?station ; gas:out1 ?depth ; gas:out2 ?pred .
gas:program gas:linkType wdt:P197 . }
FILTER(?station != wd:Q1990205)
?station wdt:P625 ?cds ;
wdt:P17 wd:Q55 .
?station p:P197 ?adjST .
?adjST ps:P197 ?adj ;
pq:P81 ?track .
?pred p:P625/psv:P625/wikibase:geoLatitude ?lat1 ; p:P625/psv:P625/wikibase:geoLongitude ?lon1 .
?station p:P625/psv:P625/wikibase:geoLatitude ?lat2 ; p:P625/psv:P625/wikibase:geoLongitude ?lon2 .
BIND(CONCAT('LINESTRING(', STR(?lon1), ' ', STR(?lat1), ',', STR(?lon2), ' ', STR(?lat2), ')') AS ?str) . BIND(STRDT(?str, geo:wktLiteral) AS ?line)}
}
OPTIONAL { ?station wdt:P18 ?image .}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select ?item ?itemLabel ?string ?content ?timestamp ?user {
?item wdt:P31 wd:Q146. # find cats
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
BIND(STRAFTER(wikibase:decodeUri(str(?item)), "http://www.wikidata.org/entity/") AS ?string)
# need to make the ID something the API can understand
SERVICE wikibase:mwapi {
bd:serviceParam wikibase:endpoint "www.wikidata.org";
wikibase:api "Generator";
wikibase:limit "once";
mwapi:generator "allpages";
mwapi:gapfrom ?string;
mwapi:gapnamespace 0 ; # main namespace
mwapi:gaplimit 1; # only one
mwapi:prop "revisions";
mwapi:rvdir "newer"; # FIRST revision
mwapi:rvprop "timestamp|content|user".
?content wikibase:apiOutput 'revisions/rev/text()' . # text of first
?timestamp wikibase:apiOutput 'revisions/rev/@timestamp' . # timestamp
?user wikibase:apiOutput 'revisions/rev/@user' . # user who created it
}
}

