PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?personLabel ?item ?itemLabel ?img ?Alvin WHERE {
?person wdt:P6821 ?id.
BIND(URI(CONCAT("http://www.alvin-portal.org/alvin/view.jsf?pid=", ?id)) AS ?Alvin)
?item p:P225 ?ScienceNameStat.
?ScienceNameStat pq:P405 ?person.
minus {?item wdt:P18 ?img}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?language ?groupeLabel ?languageLabel ?sitelink
WHERE {
{
VALUES (?language ?groupe) {
(wd:Q33302 wd:Q496250)
(wd:Q150 wd:Q23492)
}
} UNION {
?language wdt:P361 ?groupe .
?groupe wdt:P361 wd:Q496250 .
}
OPTIONAL {
?sitelink schema:about ?language .
?sitelink schema:inLanguage "fr" .
?sitelink schema:isPartOf <https://fr.wikipedia.org/>.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr". }
} ORDER BY ?languageLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?label (SAMPLE(?coord) AS ?where) ?subj (?typeLabel AS ?layer) ?planimage WHERE
{ ?subj wdt:P31/wdt:P279? ?type ;
wdt:P625 ?coord ;
wdt:P31 ?type ;
wdt:P3311 ?planimage ;
rdfs:label ?label filter (lang(?label) = "en").
?type wdt:P279? wd:Q744099 ;
rdfs:label ?typeLabel filter (lang(?typeLabel) = "en").
?subj p:P625/psv:P625 ?loc. # coordinate-location statement
?loc wikibase:geoLatitude ?lat .
?loc wikibase:geoLongitude ?long .
FILTER (?lat > 49) FILTER (?lat < 63)
FILTER (?long > -10.5) FILTER (?long < 2.02)
} GROUP BY ?label ?subj ?typeLabel ?planimage

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?country ?countryLabel ?count WITH {
SELECT ?givenName ?givenNameLabel WHERE {
?givenName wdt:P31/wdt:P279* wd:Q202444;
wdt:P1705 ?givenNameLabel.
FILTER(STRSTARTS(?givenNameLabel, "X") || STRSTARTS(?givenNameLabel, "Q"))
}
} AS %givenNames WITH {
SELECT ?country (COUNT(DISTINCT ?human) AS ?count) WHERE {
INCLUDE %givenNames.
?human wdt:P31 wd:Q5;
wdt:P735 ?givenName;
wdt:P27 ?country.
}
GROUP BY ?country
} AS %countries WHERE {
INCLUDE %countries.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?p ?pLabel ?pDescription WHERE {
?p wdt:P31 wd:Q5;
wdt:P21 wd:Q6581072;
{?p wdt:P19 wd:Q145} # place of birth: UK
UNION {?p wdt:P19 ?place.
{ ?place wdt:P131?/wdt:P27 wd:Q145 } # places whose country is the UK
UNION
{ ?place wdt:P131*/wdt:P27?/wdt:P31 wd:Q3336843 } # places whose country is a constituent of the UK
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
} ORDER BY ?pLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?itemDescription ?from ?to ?img
{
?item p:P39 [ps:P39 wd:Q11696 ; pq:P580 ?from ; pq:P582 ?to ] .
{ ?item p:P106/ps:P106 wd:Q10076267 } UNION { VALUES ?item { wd:Q11812 wd:Q8612 wd:Q23 wd:Q11891 wd:Q11813 wd:Q11869 wd:Q11896 wd:Q11817 wd:Q11815 wd:Q11820 wd:Q34836 } }
OPTIONAL { ?item wdt:P18 ?img }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item1 ?image ?item1Label ?item2 ?image2 ?item2Label ?edgeLabel
WITH { SELECT ?item1 WHERE {
VALUES ?item1 {wd:Q3172160 wd:Q56024100 wd:Q524289 wd:Q164992 wd:Q524289 wd:Q6941088 wd:Q164992 wd:Q15109492 wd:Q56867532 wd:Q1646305}
} } AS %item1
WITH {SELECT (?item1 AS ?item2) WHERE {INCLUDE %item1} } AS %item2
WHERE {
INCLUDE %item1.
INCLUDE %item2.?item1 ?prop ?item2.
?edge ?dummy ?prop ; rdf:type wikibase:Property
OPTIONAL {?item1 wdt:P18 ?image}
OPTIONAL {?item2 wdt:P18 ?image2}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?men ?women ?award ?awardLabel WHERE {
{ SELECT (COUNT(?recipient_male) AS ?men) (COUNT(?recipient_female) AS ?women) ?award WHERE {
?award wdt:P31 wd:Q1792571 # art prize
{
?recipient_male wdt:P166 ?award .
?recipient_male wdt:P21 wd:Q6581097 .
}
UNION
{
?recipient_female wdt:P166 ?award .
?recipient_female wdt:P21 wd:Q6581072 .
}
}
GROUP BY ?award
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT
?area ?areaLabel
?2011
?WelshSpeakerPercentage
?geoshape
?rgb
WHERE {
?area wdt:P3896 ?geoshape .
{ SELECT ?area ?2011 ?2011_percent WHERE {
BIND(CONCAT("2001: ", ?2011_Population, " ; ", ?2011_Speakers, " ", ?2011_Percent) as ?2011)
{ SELECT ?area ?2011_Population ?2011_Speakers ?2011_Percent ?2011_percent WHERE {
BIND(CONCAT("Population: ", STR(?2011_population)) as ?2011_Population)
BIND(CONCAT("Welsh speakers: ", STR(?2011_speakers)) as ?2011_Speakers)
BIND(CONCAT("(", SUBSTR(STR(?2011_percent),0,5), "%).") as ?2011_Percent)
{ SELECT ?area ?2011_speakers ?2011_population ?2011_percent WHERE {
BIND(100 * ?2011_speakers / ?2011_population AS ?2011_percent)
{ SELECT ?area ?2011_speakers ?2011_population WHERE {
?area wdt:P31 wd:[entity:principal area of Wales] ;
p:P2936 ?2011_SpeakersStatement ;
p:P1082 ?2011_PopulationStatement .
?2011_SpeakersStatement ?pq_qual ?pq_obj .
?qual wikibase:qualifier ?pq_qual .
?2011_SpeakersStatement pq:P585 "2011-00-00T00:00:00Z"^^xsd:dateTime ;
pq:P1098 ?2011_speakers .
?2011_PopulationStatement ?pq_qual ?pq_obj .
?qual wikibase:qualifier ?pq_qual .
?2011_PopulationStatement pq:P585 "2011-00-00T00:00:00Z"^^xsd:dateTime ;
ps:P1082 ?2011_population .
} }
} }
} }
} }
BIND(
IF(?2011_percent < 10, "0-10%",
IF(?2011_percent < 20, "10-20%",
IF(?2011_percent < 30, "20-30%",
IF(?2011_percent < 40, "30-40%",
IF(?2011_percent < 50, "40-50%",
IF(?2011_percent < 60, "50-60%",
IF(?2011_percent < 70, "60-70%",
"70%+")))))))
AS ?WelshSpeakerPercentage).
BIND(
IF(?2011_percent < 10, "ffe6e6",
IF(?2011_percent < 20, "ffb3b3",
IF(?2011_percent < 30, "ff8080",
IF(?2011_percent < 40, "ff4d4d",
IF(?2011_percent < 50, "ff1a1a",
IF(?2011_percent < 60, "e60000",
IF(?2011_percent < 70, "b30000",
"800000")))))))
AS ?rgb).
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?WelshSpeakerPercentage

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?i_ (SAMPLE(?lemma) as ?lemma_) ?layer ?place ?placeLabel ?cds
WITH {
SELECT (SAMPLE(?i) as ?i_) ?lang ?place ?cds {
?i dct:language ?lang ; ontolex:sense/wdt:P6084 ?place. OPTIONAL { ?place wdt:P625 ?cds }
} GROUP BY ?lang ?place ?cds
} AS %places
WHERE { INCLUDE %places.
?i_ wikibase:lemma ?lemma.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". ?lang rdfs:label ?layer. ?place rdfs:label ?placeLabel }
}
GROUP BY ?layer ?placeLabel ?place ?cds ?i_

PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?label (COUNT(?street) AS ?count) (GROUP_CONCAT(?street) AS ?streets) WHERE {
?street wdt:P31/wdt:P279* wd:Q79007;
wdt:P17 wd:Q183;
wdt:P131+ wd:Q64. hint:Prior hint:gearing "forward".
?street rdfs:label ?label.
FILTER(LANG(?label) = "de")
}
GROUP BY ?label
HAVING(?count > 1)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

# Find parent taxon shared by two taxa:
SELECT ?via ?viaLabel ?rank ?rankLabel ?pic WHERE {
?via ^(wdt:P171*) wd:Q15314291; # Alocasia cuprea (Q15314291)
^(wdt:P171*) wd:Q1345646. # Codiaeum variegatum (Q1345646)
FILTER(NOT EXISTS {
?via2 ^(wdt:P171*) wd:Q15314291; # Alocasia cuprea (Q15314291)
^(wdt:P171*) wd:Q1345646; # Codiaeum variegatum (Q1345646)
wdt:P171 ?via.
})
OPTIONAL {
?via wdt:P18 ?pic;
wdt:P105 ?rank.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?pathway ?pathwayLabel ?pwpart ?pwpartLabel ?variant ?variantLabel ?disease?diseaseLabel WHERE {
VALUES ?predictor {p:P3354 p:P3355 p:P3356 p:P3357 p:P3358 p:P3359}
VALUES ?predictorQualifier {pq:P2175}
VALUES ?wpID {"WP2828"}
?pathway wdt:P2410 ?wpID ; # Pathways has a Wikipathways identifier
wdt:P527 ?pwpart . # which contains pathways parts
?disease wdt:P279+ wd:Q504775 . # The disease is a subclass of urinary bladder cancer
# based on annotations in the Disease ontology
?variant wdt:P3329 ?civicID ; # a variant known in CIViC
?predictor ?node ; # has a predicting relation with diseases
# labeled as being a subclass of urinary bladder cancer
wdt:P3433 ?pwpart . # variant is biological variant of
{?node ?predictorStatement ?drug_label ;
?predictorQualifier ?disease .}
UNION
{
?node ?predictorStatement ?disease .
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?geo ?layer ?image WHERE {
?item (wdt:P31/(wdt:P279*)) wd:Q11707;
wdt:P17 wd:Q39;
wdt:P166 wd:Q20824563;
wdt:P625 ?geo.
OPTIONAL {?item wdt:P18 ?image}
?item p:P166 [ps:P166 wd:Q20824563; pq:P1114 ?layer]
MINUS {?item wdt:P576 []}
SERVICE wikibase:label { bd:serviceParam wikibase:language "de". }
}

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?genderLabel (GROUP_CONCAT(DISTINCT ?occupationLabel; SEPARATOR=", ") AS ?occupations) (GROUP_CONCAT(DISTINCT ?countryLabel; SEPARATOR=", ") AS ?countries) ?death ?articles {
VALUES ?target_country { wd:Q16 wd:Q142 wd:Q39 wd:Q31 wd:Q30 } . #countries: Canada, France, Switzerland, Belgium, USA. Removing this line to get worldwide may cause a query timeout.
VALUES ?occ { wd:Q2500638 wd:Q20826540 wd:Q5 } . #occupation: creator, erudite, person. These 3 occupations will also look for subclasses. Example: Alan Turing is a cryptographer, a subclass of cryptologist, a subclass of mathematician, a subclass of scientist, a subclass of erudite.
?item wdt:P31 wd:Q5;
wdt:P21 ?gender;
wdt:P27 ?target_country;
wdt:P27 ?country;
wdt:P106/wdt:P279* ?occ ;
wdt:P106 ?occupation;
wikibase:sitelinks ?articles . #Service to count the number of articles in Wikipedia language versions. The higher the number, the greater the chances that the person is very notorious.
?item wdt:P570 ?death . hint:Prior hint:rangeSafe true .
FILTER( ?death >= "1969-01-01T00:00:00"^^xsd:dateTime && ?death < "1970-01-01T00:00:00"^^xsd:dateTime ) #death: public domain "life+50 years". Change both years to get a list in different legislation. Example for USA: life+70 years
SERVICE wikibase:label {
bd:serviceParam wikibase:language "fr,en" . #Service to retrieve the labels of items, in order of language. Example: if the label does not exist in French, the service will take the English label
?item rdfs:label ?itemLabel .
?gender rdfs:label ?genderLabel .
?occupation rdfs:label ?occupationLabel .
?country rdfs:label ?countryLabel .
} .
} GROUP BY ?item ?itemLabel ?genderLabel ?death ?articles ORDER BY DESC (?articles) #Order by the number of articles in Wikipedia language versions. The most notorious people will be at the top of the list.

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?english ?afrik (SAMPLE(?workLabel) AS ?occupation) WHERE {
?item wdt:P27 wd:Q258; wdt:P21 wd:Q6581072
MINUS{ ?englishq schema:about ?item ; schema:isPartOf <https://en.wikiquote.org/> }
MINUS{ ?afrikq schema:about ?item ; schema:isPartOf <https://af.wikiquote.org/> }
OPTIONAL{ ?english schema:about ?item ; schema:isPartOf <https://en.wikipedia.org/> }
OPTIONAL{ ?afrik schema:about ?item ; schema:isPartOf <https://af.wikipedia.org/> }
OPTIONAL{?item wdt:P106 ?work}
FILTER (BOUND(?english) || BOUND(?afrik))
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". ?item rdfs:label ?itemLabel. ?work rdfs:label ?workLabel}
} GROUP BY ?item ?itemLabel ?english ?afrik

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?itemDescription ?image ?location ?distance ?sitelink WHERE {
SERVICE wikibase:around {
?item wdt:P625 ?location.
bd:serviceParam wikibase:center "[AUTO_COORDINATES]".
bd:serviceParam wikibase:radius "1".
bd:serviceParam wikibase:distance ?distance.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,es,de". }
OPTIONAL { ?item wdt:P18 ?image. }
OPTIONAL {
?sitelink schema:about ?item.
FILTER(REGEX(STR(?sitelink), "[AUTO_LANGUAGE].wikipedia.org/wiki/"))
}
?item wdt:P31/wdt:P279* wd:Q294440.
}
ORDER BY asc(?distance)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select distinct ?movie ?movieLabel (year(?date) as ?year) ?Commons ?InternetArchive ?Youtube ?url
where {
{ ?movie wdt:P31/wdt:P279* wd:Q11424 . ?movie wdt:P10 ?Commons .}
UNION { ?movie wdt:P31/wdt:P279* wd:Q11424 . ?movie wdt:P724 ?InternetArchive .}
UNION { ?movie wdt:P31/wdt:P279* wd:Q11424 . ?movie wdt:P1651 ?Youtube .}
UNION { ?movie wdt:P31/wdt:P279* wd:Q11424 . ?movie wdt:P963 ?url .}
OPTIONAL {?movie wdt:P577 ?date.}
SERVICE wikibase:label {
bd:serviceParam wikibase:language "fr,en"
}
} ORDER BY ?date

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?meaning ?meaningLabel ?count
WITH {
SELECT ?meaning (count(?l) as ?count)
WHERE {
?l a ontolex:LexicalEntry ;
ontolex:sense ?sense.
?sense wdt:P5137 ?meaning.
}
GROUP BY ?meaning
ORDER BY desc(?count)
LIMIT 100
} AS %i
WHERE {
INCLUDE %i
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" . }
}
ORDER BY desc(?count)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?monument ?monumentLabel ?person ?personLabel (SAMPLE(?coordinates_) AS ?coordinates) (SAMPLE(?image_) AS ?image) WITH {
SELECT DISTINCT ?monument ?person WHERE {
?monument wdt:P31/wdt:P279* wd:Q4989906;
wdt:P138 ?person.
MINUS {
?monument ?wdt ?person.
FILTER(?wdt != wdt:P138)
}
?person wdt:P31 wd:Q5.
}
LIMIT 100
} AS %results WHERE {
INCLUDE %results.
OPTIONAL { ?monument wdt:P625 ?coordinates_. }
OPTIONAL { ?monument wdt:P18 ?image_. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?monument ?monumentLabel ?person ?personLabel
LIMIT 100

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?language ?languageLabel ?wikipediaLabel where {
?language wdt:P31 ?instance;
wdt:P17 wd:Q55.
FILTER (?instance in (wd:Q34770, wd:Q33384)).
OPTIONAL {
?wikipedia wdt:P31 wd:Q10876391;
wdt:P407 ?language.
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "nl,en". }
} GROUP BY ?language ?languageLabel ?wikipediaLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?proglang ?proglangLabel ?maxdate ?followers
WITH {
SELECT ?proglang (MAX(?date) as ?maxdate) WHERE {
?proglang wdt:P31 wd:Q9143;
p:P8687 ?socialmedia.
?socialmedia ps:P8687 ?followers;
pq:P6552 ?twitter;
pq:P585 ?date.
}
GROUP by ?proglang
} AS %result
WHERE {
INCLUDE %result
?proglang wdt:P31 wd:Q9143;
p:P8687 ?socialmedia.
?socialmedia ps:P8687 ?followers;
pq:P585 ?maxdate.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} ORDER BY DESC(?followers)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
?language
?languageLabel
?count
?langLemmas
WITH {
SELECT DISTINCT ?language {
[] dct:language ?language.
}
} AS %0
WITH {
SELECT DISTINCT ?language ?langLemma {
INCLUDE %0.
[]
dct:language ?language;
wikibase:lemma ?lemma.
BIND(LANG(?lemma) AS ?langLemma).
}
} AS %1
WITH {
SELECT ?language (COUNT(*) AS ?count) {
INCLUDE %1.
}
GROUP BY ?language
} AS %2
WITH {
SELECT
?language
(GROUP_CONCAT(CONCAT(?langLemma); SEPARATOR = ", ") AS ?langLemmas)
{
INCLUDE %1.
}
GROUP BY ?language
} AS %3
{
INCLUDE %2.
INCLUDE %3.
SERVICE wikibase:label {bd:serviceParam wikibase:language "[AUTO_LANGUAGE]"}.
}
ORDER BY DESC(?count) ASC(LCASE(?languageLabel))

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT (SUBSTR(STR(?type), 32) as ?type) ?typeLabel ?typeDescription (COUNT(?item) AS ?count) WHERE {
?item wdt:P195 wd:Q636400; wdt:P31 ?type; wdt:P973 ?url FILTER (STRSTARTS(STR(?url),"http://jameelcentre") ).
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
} GROUP BY ?type ?typeLabel ?typeDescription ORDER BY UCASE(?typeLabel)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?itemLabel (COUNT(distinct ?alfabet) AS ?cnt) WHERE {
?item wdt:P31/wdt:P279* wd:Q9788.
FILTER NOT EXISTS {?alfabet wdt:P31/wdt:P279* wd:Q3241972.}
FILTER NOT EXISTS {?alfabet wdt:P279+ wd:Q9788.}
FILTER NOT EXISTS {?alfabet wdt:P31/wdt:P279* wd:Q15139721.}
FILTER NOT EXISTS {?alfabet wdt:P31/wdt:P279* wd:Q10856962.}
FILTER NOT EXISTS {?alfabet wdt:P31/wdt:P279* wd:Q188725.}
?alfabet wdt:P527 ?item.
SERVICE wikibase:label {
bd:serviceParam wikibase:language "ru, en" .
}
}
GROUP BY ?item ?itemLabel
ORDER BY DESC(?cnt)

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX gas: <http://www.bigdata.com/rdf/gas#>

SELECT ?item ?itemLabel ?itemDescription ?depth {
SERVICE gas:service {
gas:program gas:gasClass "com.bigdata.rdf.graph.analytics.SSSP" ;
gas:in wd:Q312032 ;
gas:traversalDirection "Forward" ;
gas:out ?item ;
gas:out1 ?depth ;
gas:linkType wdt:P40 .
}
FILTER NOT EXISTS {?item wdt:P4638 []}
SERVICE wikibase:label {bd:serviceParam wikibase:language "en" }
}
ORDER BY DESC(?depth)
LIMIT 100

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?t ?ppLabel ?valueLabel ?rrLabel ?image
WHERE
{
{wd:Q9711 ?prop ?t FILTER (datatype(?t)=xsd:dateTime) .
?value wikibase:directClaim ?prop. }
UNION
{
wd:Q9711 ?q ?statement FILTER regex (STR(?q),"prop/P") .
?statement ?p ?t FILTER regex (STR(?p), "prop/qualifier/P") FILTER (datatype(?t)=xsd:dateTime) .
?statement ?r ?value FILTER regex (STR(?r),"prop/statement/") .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?r),1,29),"direct/"),SUBSTR(STR(?r),40))) as ?rprop)
?rr wikibase:directClaim ?rprop .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?p),1,29),"direct/"),SUBSTR(STR(?p),40))) as ?pprop)
?pp wikibase:directClaim ?pprop .
OPTIONAL {?value wdt:P18 ?image}
}
UNION
{
wd:Q9711 wdt:P800 ?value .
?value ?prop ?t FILTER (datatype(?t)=xsd:dateTime) .
?rr wikibase:directClaim wdt:P800 .
?pp wikibase:directClaim ?prop.
OPTIONAL {?value wdt:P18 ?image}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?t

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?prop ?propLabel WHERE {
?s (wdt:P31/(wdt:P279*)) wd:Q235557;
?props ?o.
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
?prop wikibase:directClaim ?props.
}
ORDER BY (?propLabel)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?wikipediaLabel ?filmcount WHERE {
?wikipedia wdt:P31 wd:Q10876391 .
?wikipedia wdt:P424 ?sprachcode .
?wikipedia rdfs:label ?wikipediaLabel
FILTER(lang(?wikipediaLabel) = "de")
{ SELECT ?sprachcode (COUNT(DISTINCT ?film) as ?filmcount) WHERE {
?film wdt:P31/wdt:P279* wd:Q11424 .
?article schema:about ?film .
?article schema:inLanguage ?sprachcode
} GROUP BY ?sprachcode
}
} ORDER BY DESC (?filmcount) LIMIT 10

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?type ?typeLabel WHERE {
{
SELECT ?item WHERE {
SERVICE wikibase:mwapi {
bd:serviceParam wikibase:endpoint "en.wikipedia.org" .
bd:serviceParam wikibase:api "Generator" .
bd:serviceParam mwapi:generator "search" .
bd:serviceParam mwapi:gsrsearch "University of Virginia" .
bd:serviceParam mwapi:gsrlimit "max" .
?item wikibase:apiOutputItem mwapi:item .
}
} LIMIT 100
}
hint:Prior hint:runFirst "true".
FILTER NOT EXISTS { ?item ?property wd:Q213439 . }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} LIMIT 100

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?iso ?countryLabel (SUM(?stars) as ?stars) ?fertility WHERE {
{SELECT DISTINCT ?country ?iso WHERE {
VALUES ?countrytypes {wd:Q6256 wd:Q3624078} # country and sovereign state
?country wdt:P31 ?countrytypes ; wdt:P298 ?iso
MINUS {?country wdt:P576 []} # Not dissolved
} }
?country wdt:P163 ?flag.
OPTIONAL{
?flag p:P180 [ps:P180 ?feature ; pq:P1114 ?stars] . # quantity of feature
?feature wdt:P279? wd:Q17504209 # type of star polygon
}
OPTIONAL { ?country wdt:P4841 ?fertility }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} GROUP BY ?iso ?countryLabel ?fertility
ORDER BY DESC(?stars) ?countryLabel

PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX nobel: <http://data.nobelprize.org/terms/>

SELECT distinct ?id (sample(?name) AS ?name) (sample(?text) AS ?text) ?motivationen ?contribution ?Documentary ?Diploma ?Nobel_Lecture ?Prize_Presentation ?Biographical ?Banquet_Speech
(sample (?coord) AS ?coord)
(sample (?img) AS ?img)
(floor(?Year/10)*10 as ?layer)
WHERE {
SERVICE <http://data.nobelprize.org/sparql> {
?laureate_nobel_uri nobel:laureateAward ?NobelAwardid.
BIND(REPLACE(str(?laureate_nobel_uri),"http://data.nobelprize.org/resource/laureate/","") AS ?id)
OPTIONAL{?laureate_nobel_uri nobel:laureateAward / nobel:year ?Year}
OPTIONAL{?NobelAwardid rdfs:label ?text}
OPTIONAL{?NobelAwardid nobel:laureate/foaf:name ?name}
OPTIONAL{?NobelAwardid nobel:category ?category}
OPTIONAL{?NobelAwardid nobel:motivation ?motivationen
FILTER (lang(?motivationen) = 'en')
}
OPTIONAL {
?NobelAwardid nobel:contribution ?contribution
FILTER (lang(?contribution) = 'en')
}
OPTIONAL {
?NobelAwardid nobel:awardFile ?NobelAwardFileF.
?NobelAwardFileF nobel:fileType <http://data.nobelprize.org/resource/filetype/Documentary>.
?NobelAwardFileF rdfs:seeAlso ?Documentary
}
OPTIONAL {
?NobelAwardid nobel:awardFile ?NobelAwardFileD.
?NobelAwardFileD nobel:fileType <http://data.nobelprize.org/resource/filetype/Nobel_Diploma>.
?NobelAwardFileD rdfs:seeAlso ?Diploma
}
OPTIONAL { # 845 st
?NobelAwardid nobel:awardFile ?NobelAwardFileL.
?NobelAwardFileL nobel:fileType <http://data.nobelprize.org/resource/filetype/Nobel_Lecture>.
?NobelAwardFileL rdfs:seeAlso ?Nobel_Lecture
}
OPTIONAL { # 3 st
?NobelAwardid nobel:awardFile ?NobelAwardFileP.
?NobelAwardFileP nobel:fileType <http://data.nobelprize.org/resource/filetype/Prize_Presentation>.
?NobelAwardFileP rdfs:seeAlso ?Prize_Presentation
}
OPTIONAL { # 66 st
?NobelAwardid nobel:awardFile ?NobelAwardFileB.
?NobelAwardFileB nobel:fileType <http://data.nobelprize.org/resource/filetype/Biographical>.
?NobelAwardFileB rdfs:seeAlso ?Biographical
}
OPTIONAL {
?NobelAwardid nobel:awardFile ?NobelAwardFileBa.
?NobelAwardFileBa nobel:fileType <http://data.nobelprize.org/resource/filetype/Banquet_Speech>.
?NobelAwardFileBa rdfs:seeAlso ?Banquet_Speech
}
}
# Match with Wikidata P2888 Exact match
?Wikidataid wdt:P2888 ?laureate_nobel_uri.
?Wikidataid wdt:P19/wdt:P625 ?coord.
OPTIONAL {?Wikidataid wdt:P18 ?img}
BIND (?Year AS ?layer)
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} group by ?id ?motivationen ?contribution ?Documentary ?Diploma ?Nobel_Lecture ?Prize_Presentation ?Biographical ?Banquet_Speech ?Year
?layer
order by desc(?Year)
